// Offline cache for the published app.
//
// Generated by scripts/fix_no_cdn.py - edit this template, not dist/sw.js. The
// release id and precache list are filled in at build time; the release is the
// commit being deployed.
//
// Assets are immutable, so they are served cache-first from this release's
// cache only. Navigations go to the network first, so a new index.html (and
// therefore a new worker) can land while online, and fall back to the cached
// shell when offline.
//
// Handover: a new worker activates straight away but never claims the open
// page, so the page the user is looking at stays on one release and the next
// reload is served entirely by the new one. The page then posts `purge`.

const VERSION = __VERSION__;
const CACHE_NAME = `icds-reports-flet-${VERSION}`;
const PRECACHE = __PRECACHE__;

async function purgeStale() {
  const keys = await caches.keys();
  await Promise.all(
    keys.filter((key) => key !== CACHE_NAME).map((key) => caches.delete(key)),
  );
}

self.addEventListener("install", (event) => {
  event.waitUntil(
    (async () => {
      const cache = await caches.open(CACHE_NAME);
      await cache.addAll(PRECACHE);
      // Take over as soon as possible so the next navigation gets this
      // release; not claiming in `activate` is what keeps the current page
      // consistent, not this.
      await self.skipWaiting();
    })(),
  );
});

self.addEventListener("activate", (event) => {
  event.waitUntil(purgeStale());
});

self.addEventListener("message", (event) => {
  // Only the release the page is running may purge. A page still on the
  // previous release is talking to the outgoing worker, and honouring it
  // would delete this release's cache while `install` is filling it.
  if (event.data?.purge === VERSION) {
    event.waitUntil(purgeStale());
  }
});

self.addEventListener("fetch", (event) => {
  const { request } = event;
  if (request.method !== "GET") {
    return;
  }
  if (new URL(request.url).origin !== self.location.origin) {
    return;
  }
  event.respondWith(
    request.mode === "navigate" ? networkFirst() : cacheFirst(request),
  );
});

async function cacheFirst(request) {
  const cache = await caches.open(CACHE_NAME);
  const cached = await cache.match(request);
  if (cached) {
    return cached;
  }
  const response = await fetch(request);
  if (response.ok && response.type === "basic") {
    cache.put(request, response.clone());
  }
  return response;
}

async function networkFirst() {
  const cache = await caches.open(CACHE_NAME);
  const shell = new URL("index.html", self.registration.scope);
  try {
    const response = await fetch(shell);
    if (response.ok) {
      cache.put(shell, response.clone());
    }
    return response;
  } catch {
    return (await cache.match(shell)) || Response.error();
  }
}
